namespace sv_90837df485274debb095eb4390e276b1.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Williams"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = DoctorSlots.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient data against server-side business rules.
    /// Returns a dictionary of field name → error message for any violations.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(email)] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            errors[nameof(timeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using sv_90837df485274debb095eb4390e276b1.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* ── STEP 1: Patient Information ── *@
    <div class="card mb-4">
        <div class="card-header"><strong>Step 1:</strong> Patient Information</div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label" for="patientName">Patient Name</label>
                <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
                <ValidationMessage For="() => model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <InputText id="email" class="form-control" @bind-Value="model.Email" />
                <ValidationMessage For="() => model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
                <ValidationMessage For="() => model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="insurance">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </div>
        </div>
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next &raquo;
        </button>
    }

    @* ── STEP 2: Appointment Details ── *@
    @if (showStep2)
    {
        <div class="card mb-4">
            <div class="card-header"><strong>Step 2:</strong> Appointment Details</div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label" for="doctor">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="date">Date</label>
                    <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeSlot">Time Slot</label>
                    <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.ReasonForVisit" />
                    <ValidationMessage For="() => model.ReasonForVisit" />
                </div>

                <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
                    &laquo; Back
                </button>
                <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability" disabled="@isChecking">
                    @(isChecking ? "Checking…" : "Check Availability")
                </button>
                @if (availabilityPassed)
                {
                    <button type="submit" class="btn btn-success">Book Appointment</button>
                }
            </div>
        </div>
    }
</EditForm>

@if (isBooked)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool isChecking;
    private bool availabilityPassed;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            availabilityPassed = false;
        };

        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();

        var step1Valid = true;
        if (string.IsNullOrWhiteSpace(model.PatientName))
        {
            messageStore.Add(editContext.Field(nameof(model.PatientName)), "Patient Name is required.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Email))
        {
            messageStore.Add(editContext.Field(nameof(model.Email)), "Email is required.");
            step1Valid = false;
        }
        else if (!new EmailAddressAttribute().IsValid(model.Email))
        {
            messageStore.Add(editContext.Field(nameof(model.Email)), "Invalid email format.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Phone))
        {
            messageStore.Add(editContext.Field(nameof(model.Phone)), "Phone is required.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
        {
            messageStore.Add(editContext.Field(nameof(model.InsuranceProvider)), "Insurance Provider is required.");
            step1Valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityPassed = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availableSlots = [];
        model.TimeSlot = string.Empty;
        availabilityPassed = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        // Clear previous server errors for step 2 fields
        messageStore.Clear(editContext.Field(nameof(model.Doctor)));
        messageStore.Clear(editContext.Field(nameof(model.TimeSlot)));
        messageStore.Clear(editContext.Field(nameof(model.Email)));

        // Client-side validation for step 2
        var step2Valid = true;
        if (string.IsNullOrWhiteSpace(model.Doctor))
        {
            messageStore.Add(editContext.Field(nameof(model.Doctor)), "Preferred Doctor is required.");
            step2Valid = false;
        }
        if (!model.AppointmentDate.HasValue)
        {
            messageStore.Add(editContext.Field(nameof(model.AppointmentDate)), "Date is required.");
            step2Valid = false;
        }
        else if (model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            messageStore.Add(editContext.Field(nameof(model.AppointmentDate)), "Date must be in the future.");
            step2Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.TimeSlot))
        {
            messageStore.Add(editContext.Field(nameof(model.TimeSlot)), "Time Slot is required.");
            step2Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
        {
            messageStore.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason for Visit is required.");
            step2Valid = false;
        }
        else if (model.ReasonForVisit.Length > 500)
        {
            messageStore.Add(editContext.Field(nameof(model.ReasonForVisit)),
                "Reason for Visit must be 500 characters or fewer.");
            step2Valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!step2Valid)
            return;

        // Server-side validation
        isChecking = true;

        var serverErrors = await AppointmentService.ValidatePatientAsync(
            model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);

        isChecking = false;

        if (serverErrors.Count > 0)
        {
            foreach (var (field, message) in serverErrors)
            {
                var fieldName = field switch
                {
                    "email" => nameof(model.Email),
                    "doctor" => nameof(model.Doctor),
                    "timeSlot" => nameof(model.TimeSlot),
                    _ => field
                };
                messageStore.Add(editContext.Field(fieldName), message);
            }

            editContext.NotifyValidationStateChanged();
            availabilityPassed = false;
            return;
        }

        availabilityPassed = true;
    }

    private void HandleSubmit()
    {
        if (availabilityPassed)
        {
            isBooked = true;
        }
    }

    private sealed class AppointmentModel
    {
        public string PatientName { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
        public string InsuranceProvider { get; set; } = string.Empty;
        public string Doctor { get; set; } = string.Empty;
        public DateTime? AppointmentDate { get; set; }
        public string TimeSlot { get; set; } = string.Empty;
        public string ReasonForVisit { get; set; } = string.Empty;
    }
}

