+        if (string.IsNullOrWhiteSpace(model.PatientName))
+        {
+            messageStore.Add(editContext.Field(nameof(model.PatientName)), "Patient Name is required.");
+            step1Valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(model.Email))
+        {
+            messageStore.Add(editContext.Field(nameof(model.Email)), "Email is required.");
+            step1Valid = false;
+        }
+        else if (!new EmailAddressAttribute().IsValid(model.Email))
+        {
+            messageStore.Add(editContext.Field(nameof(model.Email)), "Invalid email format.");
+            step1Valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(model.Phone))
+        {
+            messageStore.Add(editContext.Field(nameof(model.Phone)), "Phone is required.");
+            step1Valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
+        {
+            messageStore.Add(editContext.Field(nameof(model.InsuranceProvider)), "Insurance Provider is required.");
+            step1Valid = false;
+        }
+
+        editContext.NotifyValidationStateChanged();
+
+        if (step1Valid)
+        {
+            showStep2 = true;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        availabilityPassed = false;
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        availableSlots = [];
+        model.TimeSlot = string.Empty;
+        availabilityPassed = false;
+
+        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
+                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        // Clear previous server errors for step 2 fields
+        messageStore.Clear(editContext.Field(nameof(model.Doctor)));
+        messageStore.Clear(editContext.Field(nameof(model.TimeSlot)));
+        messageStore.Clear(editContext.Field(nameof(model.Email)));
+
+        // Client-side validation for step 2
+        var step2Valid = true;
+        if (string.IsNullOrWhiteSpace(model.Doctor))
+        {
+            messageStore.Add(editContext.Field(nameof(model.Doctor)), "Preferred Doctor is required.");
+            step2Valid = false;
+        }
+        if (!model.AppointmentDate.HasValue)
+        {
+            messageStore.Add(editContext.Field(nameof(model.AppointmentDate)), "Date is required.");
+            step2Valid = false;
+        }
+        else if (model.AppointmentDate.Value.Date <= DateTime.Today)
+        {
+            messageStore.Add(editContext.Field(nameof(model.AppointmentDate)), "Date must be in the future.");
+            step2Valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(model.TimeSlot))
+        {
+            messageStore.Add(editContext.Field(nameof(model.TimeSlot)), "Time Slot is required.");
+            step2Valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(model.ReasonForVisit))
+        {
+            messageStore.Add(editContext.Field(nameof(model.ReasonForVisit)), "Reason for Visit is required.");
+            step2Valid = false;
+        }
+        else if (model.ReasonForVisit.Length > 500)
+        {
+            messageStore.Add(editContext.Field(nameof(model.ReasonForVisit)),
+                "Reason for Visit must be 500 characters or fewer.");
+            step2Valid = false;
+        }
+
+        editContext.NotifyValidationStateChanged();
+
+        if (!step2Valid)
+            return;
+
+        // Server-side validation
+        isChecking = true;
+
+        var serverErrors = await AppointmentService.ValidatePatientAsync(
+            model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);
+
+        isChecking = false;
+
+        if (serverErrors.Count > 0)
+        {
+            foreach (var (field, message) in serverErrors)
+            {
+                var fieldName = field switch
+                {
+                    "email" => nameof(model.Email),
+                    "doctor" => nameof(model.Doctor),
+                    "timeSlot" => nameof(model.TimeSlot),
+                    _ => field
+                };
+                messageStore.Add(editContext.Field(fieldName), message);
+            }
+
+            editContext.NotifyValidationStateChanged();
+            availabilityPassed = false;
+            return;
+        }
+
+        availabilityPassed = true;
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityPassed)
+        {
+            isBooked = true;
+        }
+    }
+
+    private sealed class AppointmentModel
+    {
+        public string PatientName { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+        public string InsuranceProvider { get; set; } = string.Empty;
+        public string Doctor { get; set; } = string.Empty;
+        public DateTime? AppointmentDate { get; set; }
+        public string TimeSlot { get; set; } = string.Empty;
+        public string ReasonForVisit { get; set; } = string.Empty;
+    }
+}
